/**
 * Owns Debater participant snapshots, one debate window and vote-block penalties. Inputs are
 * original bodies and validated debate choices; writes record a committed debate and its penalty
 * only for the same current window. Close retires the window without converting a rejected
 * choice into a penalty.
 */
import {
  COMPONENT,
  type World,
  type RoleComponent,
  type DebatePenaltyComponent,
} from "../../../../core/domain";
import {
  captureNightLife,
  livingNightLife,
  type NightLifeScope,
} from "../../../../core/domain/night_effects";

export interface DebateParticipant {
  life: NightLifeScope;
  role: RoleComponent;
  roleId: RoleComponent["role"];
  camp: RoleComponent["camp"];
  state: RoleComponent["privateState"];
}
export interface DebateAuthority {
  id: string;
  day: number;
  actorId: number;
  targetId: number;
  stage: "challenge" | "speech" | "ballot";
  participants: ReadonlyMap<number, DebateParticipant>;
}
const active = new WeakMap<World, DebateAuthority>();
export function hasActiveDebate(world: World): boolean {
  return active.has(world);
}
const sequences = new WeakMap<World, number>();
export function nextDebateId(world: World, day: number, actorId: number, targetId: number): string {
  if (active.has(world)) throw new Error("debate_window_reentry");
  const sequence = (sequences.get(world) ?? 0) + 1;
  sequences.set(world, sequence);
  return `debate:${day}:${actorId}:${targetId}:${sequence}`;
}
const commits = new WeakMap<World, Set<number>>();
const penalties = new WeakMap<
  World,
  Map<number, { record: DebatePenaltyComponent; life: NightLifeScope }>
>();
export function captureDebateParticipant(world: World, id: number): DebateParticipant | null {
  const life = captureNightLife(world, id),
    role = world.getComponent(id, COMPONENT.Role);
  return life && role
    ? { life, role, roleId: role.role, camp: role.camp, state: role.privateState }
    : null;
}
export function sameDebateParticipant(world: World, snapshot: DebateParticipant): boolean {
  return (
    livingNightLife(world, snapshot.life) &&
    world.getComponent(snapshot.life.id, COMPONENT.Role) === snapshot.role &&
    snapshot.role.role === snapshot.roleId &&
    snapshot.role.camp === snapshot.camp &&
    snapshot.role.privateState === snapshot.state
  );
}
export function openDebate(world: World, authority: DebateAuthority): void {
  if (active.has(world)) throw new Error("debate_window_reentry");
  active.set(world, authority);
}
export function closeDebate(world: World, authority: DebateAuthority): void {
  if (active.get(world) === authority) active.delete(world);
}
export function debateAuthority(world: World, token: string | undefined): DebateAuthority | null {
  const a = active.get(world);
  return a && a.id === token ? a : null;
}
export function hasDebateCommit(world: World, id: number): boolean {
  return commits.get(world)?.has(id) === true;
}
export function commitDebate(world: World, id: number): void {
  if (hasDebateCommit(world, id)) throw new Error("debate_already_committed");
  let ids = commits.get(world);
  if (!ids) {
    ids = new Set();
    commits.set(world, ids);
  }
  ids.add(id);
}
export function blockDebateVote(world: World, id: number, sourceId: number, day: number): void {
  const life = captureNightLife(world, id);
  if (!life) return;
  const record: DebatePenaltyComponent = { day, sourceId, lifeVersion: life.version };
  let entries = penalties.get(world);
  if (!entries) {
    entries = new Map();
    penalties.set(world, entries);
  }
  entries.set(id, { record, life });
  world.addComponent(id, COMPONENT.DebatePenalty, record);
}
export function debateVoteBlocked(world: World, id: number, day: number | undefined): boolean {
  const b = penalties.get(world)?.get(id);
  return (
    !!b &&
    (day === undefined || b.record.day === day) &&
    world.getComponent(id, COMPONENT.DebatePenalty) === b.record &&
    livingNightLife(world, b.life)
  );
}

/**
 * 负责在原预定发言之前开启辩论机会，并通过本族权威结算公开发言、密封投票和处罚。
 * 输入为当前日次、原参与者、请求构造端口、Provider 与网关；输出辩论事实及是否跳过原发言。
 * Provider 等待之后仍复验原体、生命、库存与警徽；请求构造不授权行动，付款和关闭保持本族原顺序。
 * 本窗口不发布局部匿名票统计；最后复验后同步提交结果、生命绑定处罚和需要的警徽移交。
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import {
  COMPONENT,
  Role,
  Camp,
  Phase,
  type World,
  type ActionProvider,
  type GameEvent,
  type BadgeComponent,
  type VotingRightComponent,
} from "../../../../core/domain";
import { ToolGateway } from "../../../gateway/tool_gateway";
import type { ActionRequestConstructionPort } from "../../../../core/domain/actions";
import { commitSheriffBadgeChoice, badgeSuccessorEligible } from "../../sheriff/badge";
import { getDebaterState, consumeDebaterChallenge, recordDebaterChoice } from "./state";
import {
  captureDebateParticipant,
  sameDebateParticipant,
  openDebate,
  closeDebate,
  hasDebateCommit,
  commitDebate,
  blockDebateVote,
  nextDebateId,
  hasActiveDebate,
  type DebateAuthority,
} from "./authority";
/** 有限 AWA 适配：原一次预定发言之前依次进行两次公开陈述，再收集密封匿名票。 */
export class DebaterWindow {
  constructor(
    private readonly world: World,
    private readonly gateway: ToolGateway,
    private readonly events: GameEvent[],
  ) {}
  async execute(
    config: ReadonlyBoardConfig,
    requests: ActionRequestConstructionPort,
    provider: ActionProvider,
    targetId: number,
    day: number,
    isCurrent: () => boolean,
  ): Promise<{ skipSpeech: boolean }> {
    if (hasActiveDebate(this.world)) throw new Error("debate_window_reentry");
    const empty = { skipSpeech: false };
    if (!isCurrent()) return empty;
    const actorId = this.world.getEntityIdsByRole(Role.Debater).find((id) => {
      const role = this.world.getComponent(id, COMPONENT.Role),
        state = getDebaterState(role);
      return (
        id !== targetId &&
        role?.camp === Camp.Good &&
        this.world.getAliveEntityIds().includes(id) &&
        state?.remaining === 1 &&
        state.choice === null &&
        !hasDebateCommit(this.world, id)
      );
    });
    if (actorId === undefined) return empty;
    let participants = new Map(
        this.world.getAliveEntityIds().flatMap((id) => {
          const p = captureDebateParticipant(this.world, id);
          return p ? [[id, p] as const] : [];
        }),
      ),
      actor = participants.get(actorId),
      target = participants.get(targetId);
    if (!actor || !target) return empty;
    const state = getDebaterState(actor.role)!,
      policy = state.policy;
    if (policy !== "awa_melbourne_2026_speech_gap_v1") return empty;
    const badgeSnapshot = (id: number) => {
      const badge = this.world.getComponent(id, COMPONENT.Badge),
        vote = this.world.getComponent(id, COMPONENT.VotingRight);
      return {
        id,
        badge,
        vote,
        isSheriff: badge?.isSheriff,
        destroyed: badge?.destroyed,
        weight: badge?.voteWeight,
        handoff: badge?.handoffPolicy,
        canVote: vote?.canVote,
        voteWeight: vote?.weight,
      };
    };
    const badges = [badgeSnapshot(actorId), badgeSnapshot(targetId)];
    const sameBadges = () =>
      badges.every(
        (b) =>
          this.world.getComponent(b.id, COMPONENT.Badge) === b.badge &&
          this.world.getComponent(b.id, COMPONENT.VotingRight) === b.vote &&
          b.badge?.isSheriff === b.isSheriff &&
          b.badge?.destroyed === b.destroyed &&
          b.badge?.voteWeight === b.weight &&
          b.badge?.handoffPolicy === b.handoff &&
          b.vote?.canVote === b.canVote &&
          b.vote?.weight === b.voteWeight,
      );
    const authority: DebateAuthority = {
      id: nextDebateId(this.world, day, actorId, targetId),
      day,
      actorId,
      targetId,
      stage: "challenge",
      participants,
    };
    // accepted 仅在两字段写完后置真；choice 保原对象身份，供等待后的状态复验。
    let accepted = false,
      choice: typeof state.choice = null;
    const current = () =>
      isCurrent() &&
      sameDebateParticipant(this.world, actor) &&
      sameDebateParticipant(this.world, target) &&
      getDebaterState(actor.role) === state &&
      state.policy === policy &&
      state.remaining === (accepted ? 0 : 1) &&
      state.choice === choice &&
      (choice === null || (choice.day === day && choice.targetId === targetId)) &&
      hasDebateCommit(this.world, actorId) === accepted &&
      sameBadges();
    const extras = {
      debate_id: authority.id,
      debate_actor_id: actorId,
      debate_target_id: targetId,
      allow_fallback: false,
    };
    const canceled = () => {
      if (isCurrent())
        this.events.push({
          timestamp: Date.now(),
          type: "debate_canceled",
          payload: { actorId, targetId, day, reason: "scope_changed" },
        });
      return empty;
    };
    openDebate(this.world, authority);
    try {
      const request = requests.create({
        actorId,
        phase: Phase.Day,
        allowedTools: ["challenge"],
        stage: "debate_challenge",
        requiresAction: false,
        summary: { key: "request.summary.debate_challenge", parameters: { target: targetId } },
        context: extras,
      });
      if (!current()) return empty;
      const action = await provider.getAction(request);
      if (!current() || action?.name !== "challenge") return empty;
      const checked = this.gateway.validateAndSanitize(this.world, actorId, action, {
        phase: Phase.Day,
        day,
        debateId: authority.id,
      });
      if (!checked.ok || !current()) return empty;
      participants = new Map(
        this.world.getAliveEntityIds().flatMap((id) => {
          const p = captureDebateParticipant(this.world, id);
          return p ? [[id, p] as const] : [];
        }),
      );
      authority.participants = participants;
      // 提交账本先于库存；局部 choice 在保存槽之前创建，setter 失败时不回滚这些前缀。
      commitDebate(this.world, actorId);
      consumeDebaterChallenge(state);
      choice = { day, targetId };
      recordDebaterChoice(state, choice);
      accepted = true;
      this.events.push(
        { timestamp: Date.now(), type: "debater_revealed", payload: { actorId, day } },
        { timestamp: Date.now(), type: "debate_started", payload: { actorId, targetId, day } },
      );
      authority.stage = "speech";
      for (const speaker of [actorId, targetId]) {
        if (!current()) return canceled();
        const speechRequest = requests.create({
          actorId: speaker,
          phase: Phase.Day,
          allowedTools: ["speak"],
          stage: "debate_speech",
          requiresAction: true,
          summary: { key: "request.summary.debate_speech" },
          context: extras,
        });
        if (!current()) return canceled();
        const speech = await provider.getAction(speechRequest);
        if (!current()) return canceled();
        if (speech?.name !== "speak") continue;
        const valid = this.gateway.validateAndSanitize(this.world, speaker, speech, {
          phase: Phase.Day,
          day,
        });
        if (!current()) return canceled();
        if (valid.ok && valid.sanitizedCall?.name === "speak")
          this.events.push({
            timestamp: Date.now(),
            type: "debate_speech",
            payload: { actorId: speaker, text: valid.sanitizedCall.args.text },
          });
      }
      authority.stage = "ballot";
      // 调用任何 Provider 之前构造完整票轮；中间统计或单人票不会提前发布。
      const ballotRequests = [...participants.keys()].map((voterId) => ({
        voterId,
        request: requests.create({
          actorId: voterId,
          phase: Phase.Day,
          allowedTools: ["debate_vote"],
          stage: "debate_ballot",
          requiresAction: true,
          summary: { key: "request.summary.debate_ballot" },
          context: extras,
        }),
      }));
      if (!current()) return canceled();
      const replies = await Promise.all(
        ballotRequests.map(async ({ voterId, request }) => ({
          voterId,
          call:
            current() && sameDebateParticipant(this.world, participants.get(voterId)!)
              ? await provider.getAction(request)
              : null,
        })),
      );
      if (!current()) return canceled();
      const ballots = replies.map(({ voterId, call }) => {
        const p = participants.get(voterId)!;
        if (!sameDebateParticipant(this.world, p) || call?.name !== "debate_vote")
          return { voterId, support: null };
        const checked = this.gateway.validateAndSanitize(this.world, voterId, call, {
          phase: Phase.Day,
          day,
          debateId: authority.id,
        });
        return {
          voterId,
          support:
            checked.ok &&
            checked.sanitizedCall?.name === "debate_vote" &&
            sameDebateParticipant(this.world, p)
              ? checked.sanitizedCall.args.support
              : null,
        };
      });
      if (!current()) return canceled();
      // 已收票再次逐人复验，另一位玩家的校验可能撤销其原体资格。
      for (const ballot of ballots)
        if (!sameDebateParticipant(this.world, participants.get(ballot.voterId)!))
          ballot.support = null;
      const eligibleCount = participants.size,
        supports = ballots.filter((b) => b.support === true).length,
        rejects = ballots.filter((b) => b.support === false).length,
        abstentions = eligibleCount - supports - rejects,
        success = supports > eligibleCount / 2,
        blockedId = success ? targetId : actorId;
      const targetBadge = this.world.getComponent(targetId, COMPONENT.Badge),
        needsBadge = success && targetBadge?.isSheriff === true && !targetBadge.destroyed;
      if (needsBadge && !badgeSuccessorEligible(this.world, targetId, actorId)) return canceled();
      if (!current()) return canceled();
      // 最后复验之后同步提交结果、绑定原生命的处罚以及需要的警徽移交。
      if (needsBadge)
        commitSheriffBadgeChoice(this.world, targetId, "debate", this.events, actorId);
      blockDebateVote(this.world, blockedId, actorId, day);
      this.events.push(
        {
          timestamp: Date.now(),
          type: "debate_ballots_recorded",
          payload: { actorId, targetId, day, eligibleCount, ballots },
        },
        {
          timestamp: Date.now(),
          type: "debate_resolved",
          payload: {
            actorId,
            targetId,
            day,
            eligibleCount,
            supports,
            rejects,
            abstentions,
            success,
            blockedId,
          },
        },
      );
      return { skipSpeech: success };
    } finally {
      closeDebate(this.world, authority);
    }
  }
}

/**
 * 负责 杠精 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { z } from "zod";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { text, roleName } from "@ai-werewolf-arena/game-text";
import {
  COMPONENT,
  Role,
  Camp,
  Phase,
  DEBATER_POLICIES,
  type RoleComponent,
} from "../../../../core/domain";
import type { NativeRoleContributions } from "../contracts";
import { numberOrNull } from "../../llm/helpers";
import { getDebaterState, projectDebaterState, initializeDebaterState } from "./state";
import { debateAuthority, hasDebateCommit, sameDebateParticipant } from "./authority";
const parameters = z.strictObject({
  policy: z.enum(DEBATER_POLICIES).default("awa_melbourne_2026_speech_gap_v1"),
});
export const DEBATER_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    role: Role.Debater,
    camp: Camp.Good,
    goodSide: "god",
    maxCount: 1,
    label: roleName("debater"),
    skillBrief: text("zh-CN", "role.debater.brief"),
    supportedBoardRoles: [
      Role.Debater,
      Role.Wolf,
      Role.Villager,
      Role.Seer,
      Role.Witch,
      Role.Hunter,
      Role.Guard,
      Role.Idiot,
      Role.WolfKing,
      Role.WhiteWolfKing,
      Role.Knight,
    ],
  },
  runtime: {
    init: initializeDebaterState,
    configuration: {
      schema: parameters,
      defaults: { policy: "awa_melbourne_2026_speech_gap_v1" },
      apply: (config, value) => ({ ...config, debater: parameters.parse(value) }),
      serialize: (config) => parameters.parse(config.debater ?? {}),
    },
    toolSpecs: [
      {
        name: "challenge",
        parameters: {
          type: "object",
          properties: { target_id: { type: "integer" } },
          required: ["target_id"],
          additionalProperties: false,
        },
        argHint: 'challenge args: {"target_id":number}',
        userPromptHintKey: "action.challenge.hint",
      },
    ],
    validationRules: {
      challenge: ({ world, actorId, day, phase, toolCall, debateId }) => {
        const a = debateAuthority(world, debateId),
          role = world.getComponent(actorId, COMPONENT.Role),
          state = getDebaterState(role);
        if (toolCall.name !== "challenge") return { code: RuleError.ToolMismatch };
        if (
          role?.role !== Role.Debater ||
          role.camp !== Camp.Good ||
          !a ||
          a.stage !== "challenge" ||
          a.actorId !== actorId ||
          a.day !== day ||
          phase !== Phase.Day ||
          !state ||
          state.remaining !== 1 ||
          state.choice !== null ||
          hasDebateCommit(world, actorId)
        )
          return { code: RuleError.DebateUnavailable };
        if (
          toolCall.args.target_id !== a.targetId ||
          actorId === a.targetId ||
          !a.participants.has(actorId) ||
          !a.participants.has(a.targetId) ||
          !sameDebateParticipant(world, a.participants.get(actorId)!) ||
          !sameDebateParticipant(world, a.participants.get(a.targetId)!)
        )
          return { code: RuleError.DebateTarget };
        return null;
      },
    },
    baselineAction: (_role, request) =>
      request.allowedTools.includes("challenge") && request.context.debate_target_id !== undefined
        ? { name: "challenge", args: { target_id: request.context.debate_target_id } }
        : null,
    llmRepair: {
      coerce: {
        challenge: (args) => {
          const target = numberOrNull(args.target_id);
          return target === null ? null : { target_id: target };
        },
      },
    },
  },
  presentation: nativeRolePresentation("debater"),
};

/**
 * 提供通用工具的原校验集合：匿名墙检查作者／窗口，辩论检查参与者／阶段，放逐票检查票权与候选。输入为网关上下文和工具参数；返回既有 RuleError 或 null，不在校验中提交资源或阶段。
 */
import { readWallTool } from "@ai-werewolf-arena/game-contract/facts/wall-notes";
import { authorizedWallAuthor } from "../events/wall_notes/authority";
import { prohibitsLoversVote } from "../roles/cupid/relation";
import { RuleError } from "@ai-werewolf-arena/game-contract";
/** 文件说明：定义通用工具的校验规则。 */
import { ToolRuleMap } from "../validation/contracts";
import { debateAuthority, sameDebateParticipant } from "../roles/debater/authority";
import { Phase } from "../../../core/domain";
import { canBeExiled, canVoteExile } from "./participation";

/** 通用工具校验规则集合。 */
export const COMMON_VALIDATION_RULES: ToolRuleMap = {
  write_note: ({ world, actorId, day, phase, toolCall, wallScope, wallId, itemInstanceId }) => {
    if (
      day !== 1 ||
      phase !== Phase.Voting ||
      !authorizedWallAuthor(world, actorId, wallId, itemInstanceId, wallScope)
    )
      return { code: RuleError.WallNoteUnavailable };
    return readWallTool(toolCall) ? null : { code: RuleError.WallNoteText };
  },
  debate_vote: ({ world, actorId, day, phase, toolCall, debateId }) => {
    const a = debateAuthority(world, debateId),
      actor = a?.participants.get(actorId);
    if (toolCall.name !== "debate_vote") return { code: RuleError.ToolMismatch };
    if (
      !a ||
      !actor ||
      a.stage !== "ballot" ||
      a.day !== day ||
      phase !== Phase.Day ||
      !sameDebateParticipant(world, actor)
    )
      return { code: RuleError.DebateUnavailable };
    if (
      toolCall.args.support !== true &&
      toolCall.args.support !== false &&
      toolCall.args.support !== null
    )
      return { code: RuleError.DebateBallot };
    return null;
  },
  report_bug: ({ toolCall }) => {
    if (toolCall.name !== "report_bug") {
      return { code: RuleError.ToolMismatch };
    }
    const { category, severity, message } = toolCall.args;
    const categorySet = new Set(["flow", "rule", "state", "logging", "other"]);
    const severitySet = new Set(["low", "medium", "high", "critical"]);
    if (!categorySet.has(String(category))) {
      return { code: RuleError.ReportCategory };
    }
    if (!severitySet.has(String(severity))) {
      return { code: RuleError.ReportSeverity };
    }
    if (typeof message !== "string" || message.trim().length === 0) {
      return { code: RuleError.ReportMessageEmpty };
    }
    if (message.length > 300) {
      return { code: RuleError.ReportMessageLong };
    }
    return null;
  },
  speak: () => null,
  vote: ({ world, actorId, day, toolCall, roleCatalog, exileCandidates }) => {
    if (toolCall.name !== "vote") {
      return { code: RuleError.ToolMismatch };
    }
    if (exileCandidates?.includes(actorId)) return { code: RuleError.PkVoteEligibility };
    if (
      !toolCall.args.abstain &&
      exileCandidates &&
      !exileCandidates.includes(toolCall.args.target_id!)
    )
      return { code: RuleError.PkVoteTarget };
    if (!canVoteExile(world, actorId, day, roleCatalog)) {
      return { code: RuleError.VoteRight };
    }
    if (toolCall.args.abstain) {
      return null;
    }
    if (toolCall.args.target_id === null) {
      return { code: RuleError.VoteTarget };
    }
    if (prohibitsLoversVote(world, actorId, toolCall.args.target_id))
      return { code: RuleError.LoversVote };
    if (!canBeExiled(world, toolCall.args.target_id, roleCatalog)) {
      return { code: RuleError.VoteTarget };
    }
    return null;
  },
};

/**
 * 负责盗贼／千面人的初始选择 scope 与请求绑定。输入为原 World 参与者、首夜请求及装配端构造依赖；
 * 输出保留原选择结果与请求绑定；setup 仍当前时调用数据所有者写选择，再沿原物理换牌／身份安装顺序提交。
 * 工厂在原 scope 复验之后才 new，固定日次仍为 1；构造／请求异常保留已开准备前缀并由原 finally 关闭。
 * 失败选择与已关闭 setup 保留原终结决定；构造端口和元数据均不携带行动许可。
