import { playerDataField } from "../player-state-data";
import type { RoleInitializationComponent, RoleInitContext } from "../contracts";
export function getDebaterState(role: RoleComponent | undefined): DebaterReadState | undefined {
  return playerDataField(playerDataField(role, "privateState"), "debater") as
    DebaterReadState | undefined;
}
/** 提交标记只使玩家视图的 remaining 归零；不写原槽，选择仅在日期与编号为正整数时输出。 */
export function projectDebaterState(state: DebaterReadState, committed = false) {
  const choice = playerDataField(state, "choice"),
    day = playerDataField(choice, "day"),
    targetId = playerDataField(choice, "targetId");
  return {
    policy: "awa_melbourne_2026_speech_gap_v1" as const,
    remaining:
      !committed && playerDataField(state, "remaining") === 1 ? (1 as const) : (0 as const),
    choice:
      typeof day === "number" &&
      Number.isSafeInteger(day) &&
      day > 0 &&
      typeof targetId === "number" &&
      Number.isSafeInteger(targetId) &&
      targetId > 0
        ? { day, targetId }
        : null,
  };
}

/** 原初始化完整正文：仅槽不存在时安装；政策 getter 或赋值失败照原表达式传播。 */
export function initializeDebaterState(role: RoleInitializationComponent, ctx: RoleInitContext): void {
  if (!getDebaterState(role))
    role.privateState.debater = {
      policy: ctx.boardConfig?.debater?.policy ?? "awa_melbourne_2026_speech_gap_v1",
      remaining: 1,
      choice: null,
    };
}

/** 原辩论提交已记账；只消费捕获状态，不再读取角色或在后续 choice 写入失败时退款。 */
export function consumeDebaterChallenge(state: DebaterReadState): void {
  (state as Pick<DebaterState, "remaining">).remaining = 0;
}

/** 接收窗口已创建的同一 choice 引用；不复制数据、不设置窗口局部值或提交 accepted 标记。 */
export function recordDebaterChoice(state: DebaterReadState, choice: DebaterReadState["choice"]): void {
  (state as Pick<DebaterState, "choice">).choice = choice;
}

/**
 * 负责拥有盗贼／变形者发到的卡、原手牌与首夜设置状态。
 * 输入为已安装阵容和明确选牌；输出为库存、设置状态和玩家 setup 数据副本。
 * 原 World 对应的 deal owner 持有手牌及参与者快照；关闭后保留选牌身份，后续角色替换
 * 不重新发库存，副本不授予 live 选择权限。
 */
import {
  captureNightLife,
  livingNightLife,
  type NightLifeScope,
} from "../../../../core/domain/night_effects";
import { copyEventData } from "@ai-werewolf-arena/game-contract";
import { COMPONENT, type RoleComponent, Role, type World } from "../../../../core/domain";
export interface InitialIdentityCard {
  cardId: string;
  role: Role;
}
export type InitialIdentitySlot = 0 | 1;
export type InitialIdentitySetupStatus = "pending" | "complete" | "cancelled" | "failed";
export interface InitialIdentityDeal {
  readonly initialRoles: readonly Role[];
  readonly candidateCounts: ReadonlyMap<Role, number>;
  readonly hands: Map<number, InitialIdentityCard>;
  readonly reserve: [InitialIdentityCard, InitialIdentityCard];
  status: InitialIdentitySetupStatus;
  selection: { actorId: number; slot: InitialIdentitySlot | null; role: Role } | null;
}
export type InitialIdentityKind = "thief" | "shapeshifter";
export const INITIAL_IDENTITY_POLICIES = Object.freeze({
  thief: "lui_meme_thief_two_extra_villagers_v1",
  shapeshifter: "awa_netease_shapeshifter_two_extra_villagers_v1",
} as const);
interface DealOwner {
  kind: InitialIdentityKind;
  deal: InitialIdentityDeal;
  cards: readonly InitialIdentityCard[];
  initialCards: readonly InitialIdentityCard[];
  playerIds: readonly number[];
  hands: Map<number, InitialIdentityCard>;
  reserve: [InitialIdentityCard, InitialIdentityCard];
  status: InitialIdentitySetupStatus;
  selection: InitialIdentityDeal["selection"];
  selectionSnapshot: InitialIdentityDeal["selection"];
  players: InitialPlayer[];
}
interface InitialPlayer {
  id: number;
  role: RoleComponent;
  roleId: Role;
  camp: RoleComponent["camp"];
  state: RoleComponent["privateState"];
  life: NightLifeScope;
  campComponent: unknown;
  victory: unknown;
  victoryJson: string;
}
const owned = new WeakMap<World, DealOwner>();
const opened = new WeakSet<World>(),
  active = new WeakSet<World>();
function field(value: unknown, key: string): unknown {
  if (!value || typeof value !== "object" || Array.isArray(value)) return undefined;
  const d = Object.getOwnPropertyDescriptor(value, key);
  return d && Object.hasOwn(d, "value") ? d.value : undefined;
}
export function readInitialIdentityCard(value: unknown): InitialIdentityCard | null {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  const keys = Reflect.ownKeys(value);
  if (keys.length !== 2 || !keys.every((k) => k === "cardId" || k === "role")) return null;
  const cardId = field(value, "cardId"),
    role = field(value, "role");
  return typeof cardId === "string" &&
    /^deal:[0-9]+$/.test(cardId) &&
    Object.values(Role).includes(role as Role)
    ? { cardId, role: role as Role }
